import{_ as a,o as t,c as o,a2 as r}from"./chunks/framework.CDU0sSpB.js";const u=JSON.parse('{"title":"1.3 Complete the smallest real task loop","description":"Let a task execute, ask for approval, produce results, and recover from failure.","frontmatter":{"title":"1.3 Complete the smallest real task loop","description":"Let a task execute, ask for approval, produce results, and recover from failure.","outline":[2,3]},"headers":[],"relativePath":"en/delivery/stage-1/1-3.md","filePath":"en/delivery/stage-1/1-3.md","lastUpdated":1794017073000}'),l={name:"en/delivery/stage-1/1-3.md"};function s(n,e,i,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="_1-3-complete-the-smallest-real-task-loop" tabindex="-1">1.3 Complete the smallest real task loop <a class="header-anchor" href="#_1-3-complete-the-smallest-real-task-loop" aria-label="Permalink to &quot;1.3 Complete the smallest real task loop&quot;">​</a></h1><h2 id="current-status" tabindex="-1">Current status <a class="header-anchor" href="#current-status" aria-label="Permalink to &quot;Current status&quot;">​</a></h2><ul><li><strong>Done:</strong> The local service and browser UI, durable task state, execution progress, approval preview, one-time external write, receipt, artifact storage, and failure recovery all run end to end.</li><li><strong>Boundary:</strong> External writes currently land in the local outbox or a controlled tool scope; this is not a connection to real email, calendar, or third-party accounts.</li></ul><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>Complete the smallest real task loop in the browser: after the user creates a task, the system does real work, asks for necessary approval, delivers an artifact, and recovers or hands over when something fails.</p><h2 id="how-to-do-it" tabindex="-1">How to do it <a class="header-anchor" href="#how-to-do-it" aria-label="Permalink to &quot;How to do it&quot;">​</a></h2><ol><li>Build a simple local service and browser interface; one running task at a time is enough.</li><li>When creating a task, record the goal, inputs, deadline, available scope, and allowed actions.</li><li>Use an existing execution capability to do real work in a controlled environment and show progress continuously.</li><li>Keep task state across refresh and restart; after failure, allow retry, continue, or human handover.</li><li>For external actions, show the target, content, and impact first; execute once after confirmation and keep a verifiable receipt.</li><li>Save artifacts so they can be opened and traced; explain failures and the next step.</li><li>Limit which files, accounts, and networks the system can reach, and do not expose secrets directly to execution.</li></ol>',7)])])}const m=a(l,[["render",s]]);export{u as __pageData,m as default};
